11	#ifndef CATLASS_GEMM_BLOCK_BLOCK_MMAD_PRELOAD_HPP
12	#define CATLASS_GEMM_BLOCK_BLOCK_MMAD_PRELOAD_HPP
13	
14	#include "catlass/catlass.hpp"
15	#include "catlass/arch/resource.hpp"
16	#include "catlass/coord.hpp"
17	#include "catlass/gemm_coord.hpp"
18	#include "catlass/gemm/dispatch_policy.hpp"
19	#include "catlass/gemm/helper.hpp"
20	#include "catlass/gemm/tile/tile_copy.hpp"
21	#include "catlass/gemm/tile/tile_mmad.hpp"
22	
23	namespace Catlass::Gemm::Block {
24	
25	template <
26	    bool ENABLE_UNIT_FLAG_, bool ENABLE_SHUFFLE_K_, class L1TileShape_, class L0TileShape_, class AType_, class BType_,
27	    class CType_, class BiasType_, class TileCopy_, class TileMmad_>
28	struct BlockMmad<
29	    MmadAtlasA2Preload<ENABLE_UNIT_FLAG_, ENABLE_SHUFFLE_K_>, L1TileShape_, L0TileShape_, AType_, BType_, CType_,
30	    BiasType_, TileCopy_, TileMmad_> {
31	public:
32	    // Type Aliases
33	    using DispatchPolicy = MmadAtlasA2Preload<ENABLE_UNIT_FLAG_, ENABLE_SHUFFLE_K_>;
34	    using ArchTag = typename DispatchPolicy::ArchTag;
35	    using L1TileShape = L1TileShape_;
36	    using L0TileShape = L0TileShape_;
37	    using ElementA = typename AType_::Element;
38	    using LayoutA = typename AType_::Layout;
39	    using ElementB = typename BType_::Element;
40	    using LayoutB = typename BType_::Layout;
41	    using ElementC = typename CType_::Element;
42	    using LayoutC = typename CType_::Layout;
43	    using TileMmad = TileMmad_;
44	    using CopyGmToL1A = typename TileCopy_::CopyGmToL1A;
45	    using CopyGmToL1B = typename TileCopy_::CopyGmToL1B;
46	    using CopyL1ToL0A = typename TileCopy_::CopyL1ToL0A;
47	    using CopyL1ToL0B = typename TileCopy_::CopyL1ToL0B;
48	    using CopyL0CToGm = typename TileCopy_::CopyL0CToGm;
49	    using ElementAccumulator =
50	        typename Gemm::helper::ElementAccumulatorSelector<ElementA, ElementB>::ElementAccumulator;
51	    using LayoutAInL1 = typename CopyL1ToL0A::LayoutSrc;
52	    using LayoutBInL1 = typename CopyL1ToL0B::LayoutSrc;
53	    using LayoutAInL0 = typename CopyL1ToL0A::LayoutDst;
54	    using LayoutBInL0 = typename CopyL1ToL0B::LayoutDst;
55	    using LayoutCInL0 = layout::zN;
56	
57	    using L1AAlignHelper = Gemm::helper::L1AlignHelper<ElementA, LayoutA>;
58	    using L1BAlignHelper = Gemm::helper::L1AlignHelper<ElementB, LayoutB>;
59	
60	    static constexpr bool ENABLE_UNIT_FLAG = DispatchPolicy::ENABLE_UNIT_FLAG;
61	    static constexpr bool ENABLE_SHUFFLE_K = DispatchPolicy::ENABLE_SHUFFLE_K;
62	    static constexpr uint32_t STAGES = DispatchPolicy::STAGES;
63	    static constexpr uint32_t L1A_SIZE = L1TileShape::M * L1TileShape::K * sizeof(ElementA);
64	    static constexpr uint32_t L1B_SIZE = L1TileShape::N * L1TileShape::K * sizeof(ElementB);
65	    static constexpr uint32_t L0A_SIZE = ArchTag::L0A_SIZE;
66	    static constexpr uint32_t L0B_SIZE = ArchTag::L0B_SIZE;
67	    static constexpr uint32_t L0C_SIZE = ArchTag::L0C_SIZE;
68	    static constexpr uint32_t L0A_PINGPONG_BUF_SIZE = L0A_SIZE / STAGES;
69	    static constexpr uint32_t L0B_PINGPONG_BUF_SIZE = L0B_SIZE / STAGES;
70	
71	    // Check LayoutC
72	    static_assert(std::is_same_v<LayoutC, layout::RowMajor>, "LayoutC only support RowMajor yet!");
73	
74	    // Check L1TileShape
75	    static_assert((L1A_SIZE * STAGES + L1B_SIZE * STAGES) <= ArchTag::L1_SIZE, "L1TileShape exceeding the L1 space!");
76	
77	    // Check L0TileShape
78	    static constexpr uint32_t L0A_TILE_SIZE = L0TileShape::M * L0TileShape::K * sizeof(ElementA);
79	    static constexpr uint32_t L0B_TILE_SIZE = L0TileShape::K * L0TileShape::N * sizeof(ElementB);
80	    static constexpr uint32_t L0C_TILE_SIZE = L0TileShape::M * L0TileShape::N * sizeof(ElementAccumulator);
81	    static_assert((L0A_TILE_SIZE * STAGES) <= L0A_SIZE, "L0TileShape exceeding the L0A space!");
82	    static_assert((L0B_TILE_SIZE * STAGES) <= L0B_SIZE, "L0TileShape exceeding the L0B space!");
83	    static_assert(L0C_TILE_SIZE <= L0C_SIZE, "L0TileShape exceeding the L0C space!");
84	
85	    static_assert(
86	        L1TileShape::M == L0TileShape::M && L1TileShape::N == L0TileShape::N,
87	        "The situation where the basic blocks of L1 and L0 differ on the m and n axes is not supported yet");
88	    static_assert(L0TileShape::K <= L1TileShape::K, "L0TileShape::K cannot exceed L1TileShape::K");
89	    // 32B (256b) aligned
90	    static_assert(
91	        Gemm::helper::TileShapeAlignChecker<L1TileShape, L0TileShape, ElementA, ElementB>::_ALIGN == 256,
92	        "Tile shape must be 32B aligned.");
93	
94	    /// Construct
95	    CATLASS_DEVICE
96	    BlockMmad(Arch::Resource<ArchTag>& resource, uint32_t l1BufAddrStart = 0)
97	    {
98	        uint32_t l1AOffset = l1BufAddrStart;
99	        uint32_t l1BOffset = l1BufAddrStart + L1A_SIZE * STAGES;
100	        // Init buffers
101	        for (uint32_t i = 0; i < STAGES; i++) {
102	            l1ATensorList[i] = resource.l1Buf.template GetBufferByByte<ElementA>(l1AOffset + L1A_SIZE * i);
103	            l1BTensorList[i] = resource.l1Buf.template GetBufferByByte<ElementB>(l1BOffset + L1B_SIZE * i);
104	            l0ATensorList[i] = resource.l0ABuf.template GetBufferByByte<ElementA>(L0A_PINGPONG_BUF_SIZE * i);
105	            l0BTensorList[i] = resource.l0BBuf.template GetBufferByByte<ElementB>(L0B_PINGPONG_BUF_SIZE * i);
106	
107	            l1AEventList[i] = i;
108	            l1BEventList[i] = i + STAGES;
109	            l0AEventList[i] = i;
110	            l0BEventList[i] = i + STAGES;
111	            AscendC::SetFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[i]);
112	            AscendC::SetFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[i]);
113	            AscendC::SetFlag<AscendC::HardEvent::M_MTE1>(l0AEventList[i]);
114	            AscendC::SetFlag<AscendC::HardEvent::M_MTE1>(l0BEventList[i]);
115	        }
116	        l0CTensor = resource.l0CBuf.template GetBufferByByte<ElementAccumulator>(0);
117	        AscendC::SetFlag<AscendC::HardEvent::FIX_M>(EVENT_ID0);
118	    }
119	
120	    /// Destructor
121	    CATLASS_DEVICE
122	    ~BlockMmad()
123	    {
124	        for (uint32_t i = 0; i < STAGES; i++) {
125	            AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[i]);
126	            AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[i]);
127	            AscendC::WaitFlag<AscendC::HardEvent::M_MTE1>(l0AEventList[i]);
128	            AscendC::WaitFlag<AscendC::HardEvent::M_MTE1>(l0BEventList[i]);
129	        }
130	        AscendC::WaitFlag<AscendC::HardEvent::FIX_M>(EVENT_ID0);
131	    }
132	
133	    /// Perform a block-scoped matrix multiply-accumulate
134	    CATLASS_DEVICE
135	    void operator()(
136	        AscendC::GlobalTensor<ElementA> const& gmBlockA, LayoutA const& layoutA,
137	        AscendC::GlobalTensor<ElementB> const& gmBlockB, LayoutB const& layoutB,
138	        AscendC::GlobalTensor<ElementC> const& gmBlockC, LayoutC const& layoutC,
139	        AscendC::GlobalTensor<ElementA> const& gmNextBlockA, AscendC::GlobalTensor<ElementB> const& gmNextBlockB,
140	        GemmCoord const& actualShape, GemmCoord const& actualShapeNext, bool isFirstBlock, bool hasNextBlock)
141	    {
142	        uint32_t mRound = RoundUp<L1AAlignHelper::M_ALIGNED>(actualShape.m());
143	        uint32_t nRound = RoundUp<L1BAlignHelper::N_ALIGNED>(actualShape.n());
144	
145	        auto layoutAInL1 = LayoutAInL1::template MakeLayout<ElementA>(L1TileShape::M, L1TileShape::K);
146	        auto layoutBInL1 = LayoutBInL1::template MakeLayout<ElementB>(L1TileShape::K, L1TileShape::N);
147	        auto layoutInL0C = LayoutCInL0::MakeLayoutInL0C(MakeCoord(mRound, nRound));
148	
149	        uint32_t kTileCount = CeilDiv<L1TileShape::K>(actualShape.k());
150	        uint32_t kTileCountNext = CeilDiv<L1TileShape::K>(actualShapeNext.k());
151	
152	        if constexpr (!ENABLE_UNIT_FLAG) {
153	            AscendC::WaitFlag<AscendC::HardEvent::FIX_M>(EVENT_ID0);
154	        }
155	        uint32_t startTileIdx = 0;
156	        if constexpr (ENABLE_SHUFFLE_K) {
157	            startTileIdx = AscendC::GetBlockIdx();
158	        }
159	        uint32_t firstTileIdx = startTileIdx % kTileCount;
160	        uint32_t lastTileIdx = (startTileIdx + kTileCount - 1) % kTileCount;
161	        uint32_t kActual =
162	            (firstTileIdx < kTileCount - 1) ? L1TileShape::K : (actualShape.k() - firstTileIdx * L1TileShape::K);
163	        uint32_t firstTileIdxNext = startTileIdx % kTileCountNext;
164	
165	        uint32_t mPartLoop = CeilDiv<L0TileShape::M>(mRound);
166	        uint32_t nPartLoop = CeilDiv<L0TileShape::N>(nRound);
167	
168	        // k loop
169	        for (uint32_t kLoopIdx = 0; kLoopIdx < kTileCount; kLoopIdx++) {
170	            uint32_t shuffleKIdx = (startTileIdx + kLoopIdx) % kTileCount;
171	            // Load first matrix A tile in total kernel loop from GM to L1
172	            if (shuffleKIdx == firstTileIdx && isFirstBlock) {
173	                MatrixCoord gmTileAOffset{0, shuffleKIdx * L1TileShape::K};
174	                MatrixCoord gmTileBOffset{shuffleKIdx * L1TileShape::K, 0};
175	                auto gmTileA = gmBlockA[layoutA.GetOffset(gmTileAOffset)];
176	                auto gmTileB = gmBlockB[layoutB.GetOffset(gmTileBOffset)];
177	                // Load first matrix A tile from GM to L1
178	                AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[l1ListId]);
179	                auto layoutTileA = layoutA.GetTileLayout(MakeCoord(actualShape.m(), kActual));
180	                copyGmToL1A(l1ATensorList[l1ListId], gmTileA, layoutAInL1, layoutTileA);
181	                AscendC::SetFlag<AscendC::HardEvent::MTE2_MTE1>(l1AEventList[l1ListId]);
182	
183	                // Load first matrix B tile from GM to L1
184	                AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[l1ListId]);
185	                auto layoutTileB = layoutB.GetTileLayout(MakeCoord(kActual, actualShape.n()));
186	                copyGmToL1B(l1BTensorList[l1ListId], gmTileB, layoutBInL1, layoutTileB);
187	                AscendC::SetFlag<AscendC::HardEvent::MTE2_MTE1>(l1BEventList[l1ListId]);
188	            }
189	
190	            uint32_t l1ListIdNext = (l1ListId + 1 < STAGES) ? (l1ListId + 1) : 0;
191	            uint32_t kActualNext{0};
192	
193	            // preload next tile from GM to L1
194	            if (shuffleKIdx != lastTileIdx) {
195	                uint32_t shuffleKIdxNext = (startTileIdx + kLoopIdx + 1) % kTileCount;
196	                // Get L1 tensor for next stage
197	                auto l1ATensor = l1ATensorList[l1ListIdNext];
198	                auto l1BTensor = l1BTensorList[l1ListIdNext];
199	                // Get GM tensor for next stage
200	                kActualNext = (shuffleKIdxNext < kTileCount - 1) ? L1TileShape::K :
201	                                                                   (actualShape.k() - shuffleKIdxNext * L1TileShape::K);
202	                MatrixCoord gmTileAOffset{0, shuffleKIdxNext * L1TileShape::K};
203	                MatrixCoord gmTileBOffset{shuffleKIdxNext * L1TileShape::K, 0};
204	                auto gmTileA = gmBlockA[layoutA.GetOffset(gmTileAOffset)];
205	                auto gmTileB = gmBlockB[layoutB.GetOffset(gmTileBOffset)];
206	
207	                // load next matrix A tile from GM to L1
208	                AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[l1ListIdNext]);
209	                auto layoutTileA = layoutA.GetTileLayout(MakeCoord(actualShape.m(), kActualNext));
210	                copyGmToL1A(l1ATensor, gmTileA, layoutAInL1, layoutTileA);
211	                AscendC::SetFlag<AscendC::HardEvent::MTE2_MTE1>(l1AEventList[l1ListIdNext]);
212	
213	                // load next matrix B tile from GM to L1
214	                AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[l1ListIdNext]);
215	                auto layoutTileB = layoutB.GetTileLayout(MakeCoord(kActualNext, actualShape.n()));
216	                copyGmToL1B(l1BTensor, gmTileB, layoutBInL1, layoutTileB);
217	                AscendC::SetFlag<AscendC::HardEvent::MTE2_MTE1>(l1BEventList[l1ListIdNext]);
218	            }
219	            if (shuffleKIdx == lastTileIdx && hasNextBlock) {
220	                // Get L1 tensor for next stage
221	                auto l1ATensor = l1ATensorList[l1ListIdNext];
222	                auto l1BTensor = l1BTensorList[l1ListIdNext];
223	                // Get GM tensor for next stage
224	                kActualNext = (firstTileIdxNext < kTileCountNext - 1) ?
225	                                  L1TileShape::K :
226	                                  (actualShapeNext.k() - firstTileIdxNext * L1TileShape::K);
227	                MatrixCoord gmTileAOffset{0, firstTileIdxNext * L1TileShape::K};
228	                MatrixCoord gmTileBOffset{firstTileIdxNext * L1TileShape::K, 0};
229	                auto gmTileA = gmNextBlockA[layoutA.GetOffset(gmTileAOffset)];
230	                auto gmTileB = gmNextBlockB[layoutB.GetOffset(gmTileBOffset)];
231	                // load next matrix A tile from GM to L1
232	                AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[l1ListIdNext]);
233	                auto layoutTileA = layoutA.GetTileLayout(MakeCoord(actualShapeNext.m(), kActualNext));
234	                copyGmToL1A(l1ATensor, gmTileA, layoutAInL1, layoutTileA);
235	                AscendC::SetFlag<AscendC::HardEvent::MTE2_MTE1>(l1AEventList[l1ListIdNext]);
236	
237	                // load next matrix B tile from GM to L1
238	                AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[l1ListIdNext]);
239	                auto layoutTileB = layoutB.GetTileLayout(MakeCoord(kActualNext, actualShapeNext.n()));
240	                copyGmToL1B(l1BTensor, gmTileB, layoutBInL1, layoutTileB);
241	                AscendC::SetFlag<AscendC::HardEvent::MTE2_MTE1>(l1BEventList[l1ListIdNext]);
242	            }
243	
244	            // Get L1 tensor for current stage
245	            auto l1ATensor = l1ATensorList[l1ListId];
246	            auto l1BTensor = l1BTensorList[l1ListId];
247	
248	            // Get the loop nums on L0
249	            uint32_t kPartLoop = CeilDiv<L0TileShape::K>(kActual);
250	
251	            uint32_t l0ABufId = 0;
252	            uint32_t l0BBufId = 0;
253	
254	            for (int mPartIdx = 0; mPartIdx < mPartLoop; mPartIdx++) {
255	                uint32_t mPartActual =
256	                    (mPartIdx < mPartLoop - 1) ? L0TileShape::M : (mRound - mPartIdx * L0TileShape::M);
257	
258	                for (int kPartIdx = 0; kPartIdx < kPartLoop; kPartIdx++) {
259	                    uint32_t kPartActual =
260	                        (kPartIdx < kPartLoop - 1) ? L0TileShape::K : (kActual - kPartIdx * L0TileShape::K);
261	
262	                    // Locate the current tile on L0A
263	                    auto l0ATile = l0ATensorList[l0ABufId];
264	                    LayoutAInL0 layoutAInL0 = LayoutAInL0::template MakeLayout<ElementA>(mPartActual, kPartActual);
265	                    // Locate the current tile of matrix A on L1
266	                    MatrixCoord l1AOffset{mPartIdx * L0TileShape::M, kPartIdx * L0TileShape::K};
267	                    auto l1ATile = l1ATensor[layoutAInL1.GetOffset(l1AOffset)];
268	
269	                    AscendC::WaitFlag<AscendC::HardEvent::M_MTE1>(l0AEventList[l0ABufId]);
270	                    if ((mPartIdx == 0) && (kPartIdx == 0)) {
271	                        AscendC::WaitFlag<AscendC::HardEvent::MTE2_MTE1>(l1AEventList[l1ListId]);
272	                    }
273	
274	                    copyL1ToL0A(l0ATile, l1ATile, layoutAInL0, layoutAInL1);
275	
276	                    if ((mPartIdx == mPartLoop - 1) && (kPartIdx == kPartLoop - 1)) {
277	                        AscendC::SetFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[l1ListId]);
278	                    }
279	
280	                    for (int nPartIdx = 0; nPartIdx < nPartLoop; nPartIdx++) {
281	                        uint32_t nPartActual =
282	                            (nPartIdx < nPartLoop - 1) ? L0TileShape::N : (nRound - nPartIdx * L0TileShape::N);
283	
284	                        // Locate the current tile on L0B
285	                        auto l0BTile = l0BTensorList[l0BBufId];
286	                        LayoutBInL0 layoutBInL0 = LayoutBInL0::template MakeLayout<ElementB>(kPartActual, nPartActual);
287	                        // Locate the current tile of matrix B on L1
288	                        MatrixCoord l1BOffset{kPartIdx * L0TileShape::K, nPartIdx * L0TileShape::N};
289	                        auto l1BTile = l1BTensor[layoutBInL1.GetOffset(l1BOffset)];
290	
291	                        // Wait for mmad finished
292	                        AscendC::WaitFlag<AscendC::HardEvent::M_MTE1>(l0BEventList[l0BBufId]);
293	                        // If the current tile is the first one on the k&n axis, wait for loading matrix B from GM to L1
294	                        if ((kPartIdx == 0) && (nPartIdx == 0)) {
295	                            AscendC::WaitFlag<AscendC::HardEvent::MTE2_MTE1>(l1BEventList[l1ListId]);
296	                        }
297	
298	                        // Load current tile from L1 to L0B
299	                        copyL1ToL0B(l0BTile, l1BTile, layoutBInL0, layoutBInL1);
300	
301	                        // If the current tile is the last one on the k&n axis, notify to load matrix B from GM to L1
302	                        if ((kPartIdx == kPartLoop - 1) && (nPartIdx == nPartLoop - 1)) {
303	                            AscendC::SetFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[l1ListId]);
304	                        }
305	                        // Notify to do mmad
306	                        AscendC::SetFlag<AscendC::HardEvent::MTE1_M>(EVENT_ID0);
307	
308	                        // Locate the current tile on L0C
309	                        MatrixCoord l0COffset{mPartIdx * L0TileShape::M, nPartIdx * L0TileShape::N};
310	                        auto l0CTile = l0CTensor[layoutInL0C.GetOffset(l0COffset)];
311	
312	                        // Compute the matrix multiplication on L0A and L0B and write the result to the accumulator
313	                        // Wait for loading L0B
314	                        AscendC::WaitFlag<AscendC::HardEvent::MTE1_M>(EVENT_ID0);
315	
316	                        // If the current tile is the first tile on the k axis, the accumulator needs to be reset to 0
317	                        bool initC = ((kLoopIdx == 0) && (kPartIdx == 0));
318	                        // If the unit flag is enabled, the unit flag is set according to the calculation progress
319	                        uint8_t unitFlag = 0b00;
320	                        if constexpr (ENABLE_UNIT_FLAG) {
321	                            if ((kLoopIdx == kTileCount - 1) && (mPartIdx == mPartLoop - 1) &&
322	                                (kPartIdx == kPartLoop - 1) && (nPartIdx == nPartLoop - 1)) {
323	                                unitFlag = 0b11;
324	                            } else {
325	                                unitFlag = 0b10;
326	                            }
327	                        }
328	                        // Perform calculation operations
329	                        tileMmad(l0CTile, l0ATile, l0BTile, mPartActual, nPartActual, kPartActual, initC, unitFlag);
330	
331	                        // Notify to move the next L0B tile
332	                        AscendC::SetFlag<AscendC::HardEvent::M_MTE1>(l0BEventList[l0BBufId]);
333	
334	                        l0BBufId = (l0BBufId + 1 < STAGES) ? (l0BBufId + 1) : 0;
335	                    }
336	                    AscendC::SetFlag<AscendC::HardEvent::M_MTE1>(l0AEventList[l0ABufId]);
337	                    l0ABufId = (l0ABufId + 1 < STAGES) ? (l0ABufId + 1) : 0;
338	                }
339	            }
340	
341	            l1ListId = l1ListIdNext;
342	            kActual = kActualNext;
343	        }
344	
345	        // copy block out
346	        LayoutC layoutBlock = layoutC.GetTileLayout(actualShape.GetCoordMN());
347	
348	        if constexpr (!ENABLE_UNIT_FLAG) {
349	            AscendC::SetFlag<AscendC::HardEvent::M_FIX>(EVENT_ID0);
350	            AscendC::WaitFlag<AscendC::HardEvent::M_FIX>(EVENT_ID0);
351	            copyL0CToGm(gmBlockC, l0CTensor, layoutBlock, layoutInL0C);
352	            AscendC::SetFlag<AscendC::HardEvent::FIX_M>(EVENT_ID0);
353	        } else {
354	            copyL0CToGm(gmBlockC, l0CTensor, layoutBlock, layoutInL0C, 0b11);
355	        }
356	    }
357	
358	protected:
359	    /// Data members
360	    AscendC::LocalTensor<ElementA> l1ATensorList[STAGES];
361	    AscendC::LocalTensor<ElementB> l1BTensorList[STAGES];
362	    AscendC::LocalTensor<ElementA> l0ATensorList[STAGES];
363	    AscendC::LocalTensor<ElementB> l0BTensorList[STAGES];
364	    AscendC::LocalTensor<ElementAccumulator> l0CTensor;
365	
366	    int32_t l1AEventList[STAGES];
367	    int32_t l1BEventList[STAGES];
368	    int32_t l0AEventList[STAGES];
369	    int32_t l0BEventList[STAGES];
370	
371	    uint32_t l1ListId{0};
372	
373	    TileMmad tileMmad;
374	    CopyGmToL1A copyGmToL1A;
375	    CopyGmToL1B copyGmToL1B;
376	    CopyL1ToL0A copyL1ToL0A;
377	    CopyL1ToL0B copyL1ToL0B;
378	    CopyL0CToGm copyL0CToGm;
379	};
380	
381	} // namespace Catlass::Gemm::Block
382	
383	#endif // CATLASS_GEMM_BLOCK_BLOCK_MMAD_PRELOAD_HPP
384

