20	#include "catlass/gemm/helper.hpp"
21	#include "catlass/gemm/tile/tile_copy.hpp"
22	#include "catlass/gemm/tile/tile_mmad.hpp"
23	
24	namespace Catlass::Gemm::Block {
25	
26	template <
27	    uint32_t PRELOAD_STAGES_, uint32_t L1_STAGES_, uint32_t L0A_STAGES_, uint32_t L0B_STAGES_, uint32_t L0C_STAGES_,
28	    bool ENABLE_UNIT_FLAG_, bool ENABLE_SHUFFLE_K_, class L1TileShape_, class L0TileShape_, class AType_, class BType_,
29	    class CType_, class BiasType_, class TileCopy_, class TileMmad_>
30	struct BlockMmad<
31	    MmadAtlasA2PreloadAsync<
32	        PRELOAD_STAGES_, L1_STAGES_, L0A_STAGES_, L0B_STAGES_, L0C_STAGES_, ENABLE_UNIT_FLAG_, ENABLE_SHUFFLE_K_>,
33	    L1TileShape_, L0TileShape_, AType_, BType_, CType_, BiasType_, TileCopy_, TileMmad_> {
34	public:
35	    // Type Aliases
36	    using DispatchPolicy = MmadAtlasA2PreloadAsync<
37	        PRELOAD_STAGES_, L1_STAGES_, L0A_STAGES_, L0B_STAGES_, L0C_STAGES_, ENABLE_UNIT_FLAG_, ENABLE_SHUFFLE_K_>;
38	    using ArchTag = typename DispatchPolicy::ArchTag;
39	    using L1TileShape = L1TileShape_;
40	    using L0TileShape = L0TileShape_;
41	    using ElementA = typename AType_::Element;
42	    using LayoutA = typename AType_::Layout;
43	    using ElementB = typename BType_::Element;
44	    using LayoutB = typename BType_::Layout;
45	    using ElementC = typename CType_::Element;
46	    using LayoutC = typename CType_::Layout;
47	    using TileMmad = TileMmad_;
48	    using CopyGmToL1A = typename TileCopy_::CopyGmToL1A;
49	    using CopyGmToL1B = typename TileCopy_::CopyGmToL1B;
50	    using CopyL1ToL0A = typename TileCopy_::CopyL1ToL0A;
51	    using CopyL1ToL0B = typename TileCopy_::CopyL1ToL0B;
52	    using CopyL0CToGm = typename TileCopy_::CopyL0CToGm;
53	    using ElementAccumulator =
54	        typename Gemm::helper::ElementAccumulatorSelector<ElementA, ElementB>::ElementAccumulator;
55	    using LayoutAInL1 = typename CopyL1ToL0A::LayoutSrc;
56	    using LayoutBInL1 = typename CopyL1ToL0B::LayoutSrc;
57	    using LayoutAInL0 = typename CopyL1ToL0A::LayoutDst;
58	    using LayoutBInL0 = typename CopyL1ToL0B::LayoutDst;
59	    using LayoutCInL0 = layout::zN;
60	
61	    using L1AAlignHelper = Gemm::helper::L1AlignHelper<ElementA, LayoutA>;
62	    using L1BAlignHelper = Gemm::helper::L1AlignHelper<ElementB, LayoutB>;
63	
64	    static constexpr uint32_t PRELOAD_STAGES = DispatchPolicy::PRELOAD_STAGES;
65	    static constexpr uint32_t L1_STAGES = DispatchPolicy::L1_STAGES;
66	    static constexpr uint32_t L0A_STAGES = DispatchPolicy::L0A_STAGES;
67	    static constexpr uint32_t L0B_STAGES = DispatchPolicy::L0B_STAGES;
68	    static constexpr uint32_t L0C_STAGES = DispatchPolicy::L0C_STAGES;
69	
70	    static constexpr bool ENABLE_UNIT_FLAG = DispatchPolicy::ENABLE_UNIT_FLAG;
71	    static constexpr bool ENABLE_SHUFFLE_K = DispatchPolicy::ENABLE_SHUFFLE_K;
72	
73	    // L1 tile size
74	    static constexpr uint32_t L1A_TILE_SIZE = L1TileShape::M * L1TileShape::K * sizeof(ElementA);
75	    static constexpr uint32_t L1B_TILE_SIZE = L1TileShape::N * L1TileShape::K * sizeof(ElementB);
76	    // L0 tile size
77	    static constexpr uint32_t L0A_TILE_SIZE = L0TileShape::M * L0TileShape::K * sizeof(ElementA);
78	    static constexpr uint32_t L0B_TILE_SIZE = L0TileShape::K * L0TileShape::N * sizeof(ElementB);
79	    static constexpr uint32_t L0C_TILE_SIZE = L1TileShape::M * L1TileShape::N * sizeof(ElementAccumulator);
80	
81	    // Check LayoutC
82	    static_assert(std::is_same_v<LayoutC, layout::RowMajor>, "LayoutC only support RowMajor yet!");
83	
84	    // Check L1TileShape
85	    static_assert(
86	        (L1A_TILE_SIZE + L1B_TILE_SIZE) * L1_STAGES <= ArchTag::L1_SIZE, "L1TileShape exceeding the L1 space!");
87	
88	    // Check L0TileShape
89	    static_assert(L0A_TILE_SIZE * L0A_STAGES <= ArchTag::L0A_SIZE, "L0TileShape exceeding the L0A space!");
90	    static_assert(L0B_TILE_SIZE * L0B_STAGES <= ArchTag::L0B_SIZE, "L0TileShape exceeding the L0B space!");
91	    static_assert(L0C_TILE_SIZE * L0C_STAGES <= ArchTag::L0C_SIZE, "L0TileShape exceeding the L0C space!");
92	
93	    static_assert(
94	        L1TileShape::M == L0TileShape::M && L1TileShape::N == L0TileShape::N,
95	        "The situation where the basic blocks of L1 and L0 differ on the m and n axes is not supported yet");
96	    static_assert(L0TileShape::K <= L1TileShape::K, "L0TileShape::K cannot exceed L1TileShape::K");
97	    // 32B (256b) aligned
98	    static_assert(
99	        Gemm::helper::TileShapeAlignChecker<L1TileShape, L0TileShape, ElementA, ElementB>::_ALIGN == 256,
100	        "Tile shape must be 32B aligned.");
101	
102	    static constexpr auto L1A_LAYOUT = LayoutAInL1::template MakeLayout<ElementA>(L1TileShape::M, L1TileShape::K);
103	    static constexpr auto L1B_LAYOUT = LayoutBInL1::template MakeLayout<ElementB>(L1TileShape::K, L1TileShape::N);
104	
105	    CATLASS_DEVICE
106	    BlockMmad(Arch::Resource<ArchTag>& resource, uint32_t l1BufAddrStart = 0)
107	    {
108	        InitL1(resource, l1BufAddrStart);
109	        InitL0A(resource);
110	        InitL0B(resource);
111	        InitL0C(resource);
112	    }
113	
114	    CATLASS_DEVICE
115	    ~BlockMmad()
116	    {
117	        SynchronizeBlock();
118	        for (uint32_t i = 0; i < L1_STAGES; ++i) {
119	            AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[i]);
120	            AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[i]);
121	        }
122	        for (uint32_t i = 0; i < L0A_STAGES; ++i) {
123	            AscendC::WaitFlag<AscendC::HardEvent::M_MTE1>(l0AEventList[i]);
124	        }
125	        for (uint32_t i = 0; i < L0B_STAGES; ++i) {
126	            AscendC::WaitFlag<AscendC::HardEvent::M_MTE1>(l0BEventList[i]);
127	        }
128	        for (uint32_t i = 0; i < L0C_STAGES; ++i) {
129	            AscendC::WaitFlag<AscendC::HardEvent::FIX_M>(l0CEventList[i]);
130	        }
131	    }
132	
133	    CATLASS_DEVICE
134	    void operator()(
135	        AscendC::GlobalTensor<ElementA> const& gmBlockA, LayoutA const& layoutA,
136	        AscendC::GlobalTensor<ElementB> const& gmBlockB, LayoutB const& layoutB,
137	        AscendC::GlobalTensor<ElementC> const& gmBlockC, LayoutC const& layoutC, GemmCoord const& actualShape,
138	        Callback&& callback = Callback{})
139	    {
140	        uint32_t kTileCount = CeilDiv<L1TileShape::K>(actualShape.k());
141	
142	        uint32_t mRound = RoundUp<L1AAlignHelper::M_ALIGNED>(actualShape.m());
143	        uint32_t nRound = RoundUp<L1BAlignHelper::N_ALIGNED>(actualShape.n());
144	
145	        uint32_t startTileIdx = 0;
146	        if constexpr (ENABLE_SHUFFLE_K) {
147	            startTileIdx = AscendC::GetBlockIdx() % kTileCount;
148	        }
149	
150	        for (uint32_t kLoopIdx = 0; kLoopIdx < kTileCount; ++kLoopIdx) {
151	            uint32_t kTileIdx = (startTileIdx + kLoopIdx < kTileCount) ? (startTileIdx + kLoopIdx) :
152	                                                                         (startTileIdx + kLoopIdx - kTileCount);
153	
154	            uint32_t kActual =
155	                (kTileIdx < kTileCount - 1) ? L1TileShape::K : (actualShape.k() - kTileIdx * L1TileShape::K);
156	
157	            // Emission load instruction from GM to L1
158	            MatrixCoord gmTileAOffset{0, kTileIdx * L1TileShape::K};
159	            MatrixCoord gmTileBOffset{kTileIdx * L1TileShape::K, 0};
160	            auto gmTileA = gmBlockA[layoutA.GetOffset(gmTileAOffset)];
161	            auto gmTileB = gmBlockB[layoutB.GetOffset(gmTileBOffset)];
162	            // Load first matrix A tile from GM to L1
163	            AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[l1ListId]);
164	            auto layoutTileA = layoutA.GetTileLayout(MakeCoord(actualShape.m(), kActual));
165	            copyGmToL1A(l1ATensorList[l1ListId], gmTileA, L1A_LAYOUT, layoutTileA);
166	            AscendC::SetFlag<AscendC::HardEvent::MTE2_MTE1>(l1AEventList[l1ListId]);
167	            // Load first matrix B tile from GM to L1
168	            AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[l1ListId]);
169	            auto layoutTileB = layoutB.GetTileLayout(MakeCoord(kActual, actualShape.n()));
170	            copyGmToL1B(l1BTensorList[l1ListId], gmTileB, L1B_LAYOUT, layoutTileB);
171	            AscendC::SetFlag<AscendC::HardEvent::MTE2_MTE1>(l1BEventList[l1ListId]);
172	
173	            // If the number of preload instructions reaches the upper limit, perform an mmad calculation on L1 tile
174	            if (preloadCount == PRELOAD_STAGES) {
175	                L1TileMmad(l1TileMmadParamsList[l1TileMmadParamsId]);
176	            }
177	
178	            // Store the current load status
179	            uint32_t preloadL1TileMmadParamsId = (l1TileMmadParamsId + preloadCount < PRELOAD_STAGES) ?
180	                                                     (l1TileMmadParamsId + preloadCount) :
181	                                                     (l1TileMmadParamsId + preloadCount - PRELOAD_STAGES);
182	            auto& l1TileMmadParams = l1TileMmadParamsList[preloadL1TileMmadParamsId];
183	            l1TileMmadParams.l1ListId = l1ListId;
184	            l1TileMmadParams.mRound = mRound;
185	            l1TileMmadParams.nRound = nRound;
186	            l1TileMmadParams.kActual = kActual;
187	            l1TileMmadParams.isKLoopFirst = (kLoopIdx == 0);
188	            l1TileMmadParams.isKLoopLast = (kLoopIdx == kTileCount - 1);
189	            if (kLoopIdx == kTileCount - 1) {
190	                l1TileMmadParams.gmBlockC = gmBlockC;
191	                l1TileMmadParams.layoutCInGm = layoutC.GetTileLayout(actualShape.GetCoordMN());
192	                l1TileMmadParams.callback = callback;
193	            }
194	
195	            if (preloadCount < PRELOAD_STAGES) {
196	                ++preloadCount;
197	            } else {
198	                l1TileMmadParamsId = (l1TileMmadParamsId + 1 < PRELOAD_STAGES) ? (l1TileMmadParamsId + 1) : 0;
199	            }
200	            l1ListId = (l1ListId + 1 < L1_STAGES) ? (l1ListId + 1) : 0;
201	        }
202	    }
203	
204	    CATLASS_DEVICE
205	    void SynchronizeBlock()
206	    {
207	        while (preloadCount > 0) {
208	            L1TileMmad(l1TileMmadParamsList[l1TileMmadParamsId]);
209	            l1TileMmadParamsId = (l1TileMmadParamsId + 1 < PRELOAD_STAGES) ? (l1TileMmadParamsId + 1) : 0;
210	            --preloadCount;
211	        }
212	    }
213	
214	private:
215	    struct L1TileMmadParams {
216	        uint32_t l1ListId;
217	        uint32_t mRound;
218	        uint32_t nRound;
219	        uint32_t kActual;
220	        bool isKLoopFirst;
221	        bool isKLoopLast;
222	        AscendC::GlobalTensor<ElementC> gmBlockC;
223	        LayoutC layoutCInGm;
224	        Callback callback;
225	
226	        CATLASS_DEVICE
227	        L1TileMmadParams() = default;
228	    };
229	
230	    CATLASS_DEVICE
231	    void InitL1(Arch::Resource<ArchTag>& resource, uint32_t l1BufAddrStart)
232	    {
233	        uint32_t l1AOffset = l1BufAddrStart;
234	        uint32_t l1BOffset = l1BufAddrStart + L1A_TILE_SIZE * L1_STAGES;
235	        for (uint32_t i = 0; i < L1_STAGES; ++i) {
236	            l1ATensorList[i] = resource.l1Buf.template GetBufferByByte<ElementA>(l1AOffset + L1A_TILE_SIZE * i);
237	            l1BTensorList[i] = resource.l1Buf.template GetBufferByByte<ElementB>(l1BOffset + L1B_TILE_SIZE * i);
238	            l1AEventList[i] = i;
239	            l1BEventList[i] = i + L1_STAGES;
240	            AscendC::SetFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[i]);
241	            AscendC::SetFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[i]);
242	        }
243	    }
244	
245	    CATLASS_DEVICE
246	    void InitL0A(Arch::Resource<ArchTag>& resource)
247	    {
248	        for (uint32_t i = 0; i < L0A_STAGES; ++i) {
249	            l0ATensorList[i] = resource.l0ABuf.template GetBufferByByte<ElementA>(L0A_TILE_SIZE * i);
250	            l0AEventList[i] = i;
251	            AscendC::SetFlag<AscendC::HardEvent::M_MTE1>(l0AEventList[i]);
252	        }
253	    }
254	
255	    CATLASS_DEVICE
256	    void InitL0B(Arch::Resource<ArchTag>& resource)
257	    {
258	        for (uint32_t i = 0; i < L0B_STAGES; ++i) {
259	            l0BTensorList[i] = resource.l0BBuf.template GetBufferByByte<ElementB>(L0B_TILE_SIZE * i);
260	            l0BEventList[i] = i + L0A_STAGES;
261	            AscendC::SetFlag<AscendC::HardEvent::M_MTE1>(l0BEventList[i]);
262	        }
263	    }
264	
265	    CATLASS_DEVICE
266	    void InitL0C(Arch::Resource<ArchTag>& resource)
267	    {
268	        for (uint32_t i = 0; i < L0C_STAGES; ++i) {
269	            l0CTensorList[i] = resource.l0CBuf.template GetBufferByByte<ElementAccumulator>(L0C_TILE_SIZE * i);
270	            l0CEventList[i] = i;
271	            AscendC::SetFlag<AscendC::HardEvent::FIX_M>(l0CEventList[i]);
272	        }
273	    }
274	
275	    CATLASS_DEVICE
276	    void L1TileMmad(L1TileMmadParams const& params)
277	    {
278	        uint32_t mPartLoop = CeilDiv<L0TileShape::M>(params.mRound);
279	        uint32_t nPartLoop = CeilDiv<L0TileShape::N>(params.nRound);
280	        uint32_t kPartLoop = CeilDiv<L0TileShape::K>(params.kActual);
281	        auto& l1ATensor = l1ATensorList[params.l1ListId];
282	        auto& l1BTensor = l1BTensorList[params.l1ListId];
283	
284	        auto& l0CTensor = l0CTensorList[l0CListId];
285	        LayoutCInL0 layoutCInL0 = LayoutCInL0::MakeLayoutInL0C(MakeCoord(params.mRound, params.nRound));
286	
287	        if constexpr (!ENABLE_UNIT_FLAG) {
288	            if (params.isKLoopFirst) {
289	                AscendC::WaitFlag<AscendC::HardEvent::FIX_M>(l0CEventList[l0CListId]);
290	            }
291	        }
292	
293	        for (uint32_t mPartIdx = 0; mPartIdx < mPartLoop; ++mPartIdx) {
294	            uint32_t mPartActual =
295	                (mPartIdx < mPartLoop - 1) ? L0TileShape::M : (params.mRound - mPartIdx * L0TileShape::M);
296	
297	            for (uint32_t kPartIdx = 0; kPartIdx < kPartLoop; ++kPartIdx) {
298	                uint32_t kPartActual =
299	                    (kPartIdx < kPartLoop - 1) ? L0TileShape::K : (params.kActual - kPartIdx * L0TileShape::K);
300	
301	                auto& l0ATile = l0ATensorList[l0AListId];
302	                auto layoutAInL0 = LayoutAInL0::template MakeLayout<ElementA>(mPartActual, kPartActual);
303	                auto l1AOffset = MakeCoord(mPartIdx, kPartIdx) * L0TileShape::ToCoordMK();
304	                auto l1ATile = l1ATensor[L1A_LAYOUT.GetOffset(l1AOffset)];
305	
306	                AscendC::WaitFlag<AscendC::HardEvent::M_MTE1>(l0AEventList[l0AListId]);
307	                if ((mPartIdx == 0) && (kPartIdx == 0)) {
308	                    AscendC::WaitFlag<AscendC::HardEvent::MTE2_MTE1>(l1AEventList[params.l1ListId]);
309	                }
310	                copyL1ToL0A(l0ATile, l1ATile, layoutAInL0, L1A_LAYOUT);
311	                if ((mPartIdx == mPartLoop - 1) && (kPartIdx == kPartLoop - 1)) {
312	                    AscendC::SetFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[params.l1ListId]);
313	                }
314	
315	                for (uint32_t nPartIdx = 0; nPartIdx < nPartLoop; ++nPartIdx) {
316	                    uint32_t nPartActual =
317	                        (nPartIdx < nPartLoop - 1) ? L0TileShape::N : (params.nRound - nPartIdx * L0TileShape::N);
318	
319	                    auto& l0BTile = l0BTensorList[l0BListId];
320	                    auto layoutBInL0 = LayoutBInL0::template MakeLayout<ElementB>(kPartActual, nPartActual);
321	                    auto l1BOffset = MakeCoord(kPartIdx, nPartIdx) * L0TileShape::ToCoordKN();
322	                    auto l1BTile = l1BTensor[L1B_LAYOUT.GetOffset(l1BOffset)];
323	
324	                    AscendC::WaitFlag<AscendC::HardEvent::M_MTE1>(l0BEventList[l0BListId]);
325	                    if ((kPartIdx == 0) && (nPartIdx == 0)) {
326	                        AscendC::WaitFlag<AscendC::HardEvent::MTE2_MTE1>(l1BEventList[params.l1ListId]);
327	                    }
328	                    copyL1ToL0B(l0BTile, l1BTile, layoutBInL0, L1B_LAYOUT);
329	                    if ((kPartIdx == kPartLoop - 1) && (nPartIdx == nPartLoop - 1)) {
330	                        AscendC::SetFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[params.l1ListId]);
331	                    }
332	
333	                    AscendC::SetFlag<AscendC::HardEvent::MTE1_M>(EVENT_ID0);
334	
335	                    auto l0COffset = MakeCoord(mPartIdx, nPartIdx) * L0TileShape::ToCoordMN();
336	                    auto l0CTile = l0CTensor[layoutCInL0.GetOffset(l0COffset)];
337	
338	                    AscendC::WaitFlag<AscendC::HardEvent::MTE1_M>(EVENT_ID0);
339	                    // If the current tile is the first tile on the k axis, the accumulator needs to be reset to 0
340	                    bool initC = (params.isKLoopFirst && (kPartIdx == 0));
341	                    // If the unit flag is enabled, the unit flag is set according to the calculation progress
342	                    uint8_t unitFlag = 0b00;
343	                    if constexpr (ENABLE_UNIT_FLAG) {
344	                        if (params.isKLoopLast && (mPartIdx == mPartLoop - 1) && (kPartIdx == kPartLoop - 1) &&
345	                            (nPartIdx == nPartLoop - 1)) {
346	                            unitFlag = 0b11;
347	                        } else {
348	                            unitFlag = 0b10;
349	                        }
350	                    }
351	                    tileMmad(l0CTile, l0ATile, l0BTile, mPartActual, nPartActual, kPartActual, initC, unitFlag);
352	
353	                    AscendC::SetFlag<AscendC::HardEvent::M_MTE1>(l0BEventList[l0BListId]);
354	                    l0BListId = (l0BListId + 1 < L0B_STAGES) ? (l0BListId + 1) : 0;
355	                }
356	                AscendC::SetFlag<AscendC::HardEvent::M_MTE1>(l0AEventList[l0AListId]);
357	                l0AListId = (l0AListId + 1 < L0A_STAGES) ? (l0AListId + 1) : 0;
358	            }
359	        }
360	
361	        if (params.isKLoopLast) {
362	            auto layoutCInGm = params.layoutCInGm;
363	
364	            if constexpr (!ENABLE_UNIT_FLAG) {
365	                AscendC::SetFlag<AscendC::HardEvent::M_FIX>(l0CEventList[l0CListId]);
366	                AscendC::WaitFlag<AscendC::HardEvent::M_FIX>(l0CEventList[l0CListId]);
367	                copyL0CToGm(params.gmBlockC, l0CTensor, layoutCInGm, layoutCInL0);
368	                AscendC::SetFlag<AscendC::HardEvent::FIX_M>(l0CEventList[l0CListId]);
369	            } else {
370	                copyL0CToGm(params.gmBlockC, l0CTensor, layoutCInGm, layoutCInL0, 0b11);
371	            }
372	            l0CListId = (l0CListId + 1 < L0C_STAGES) ? (l0CListId + 1) : 0;
373	
374	            if (params.callback) {
375	                params.callback();
376	            }
377	        }
378	    }
379	
380	    AscendC::LocalTensor<ElementA> l1ATensorList[L1_STAGES];
381	    AscendC::LocalTensor<ElementB> l1BTensorList[L1_STAGES];
382	    int32_t l1AEventList[L1_STAGES];
383	    int32_t l1BEventList[L1_STAGES];
384	    uint32_t l1ListId{0};
385	
386	    AscendC::LocalTensor<ElementA> l0ATensorList[L0A_STAGES];
387	    int32_t l0AEventList[L0A_STAGES];
388	    uint32_t l0AListId{0};
389	
390	    AscendC::LocalTensor<ElementB> l0BTensorList[L0B_STAGES];
391	    int32_t l0BEventList[L0B_STAGES];
392	    uint32_t l0BListId{0};
393	
394	    AscendC::LocalTensor<ElementAccumulator> l0CTensorList[L0C_STAGES_];
395	    int32_t l0CEventList[L0C_STAGES_];
396	    uint32_t l0CListId{0};
397	
398	    L1TileMmadParams l1TileMmadParamsList[PRELOAD_STAGES];
399	    uint32_t l1TileMmadParamsId{0};
400	    uint32_t preloadCount{0};
401	
402	    TileMmad tileMmad;
403	    CopyGmToL1A copyGmToL1A;
404	    CopyGmToL1B copyGmToL1B;
405	    CopyL1ToL0A copyL1ToL0A;
406	    CopyL1ToL0B copyL1ToL0B;
407	    CopyL0CToGm copyL0CToGm;
408	};
409	
410	} // namespace Catlass::Gemm::Block
411	
412	#endif // CATLASS_GEMM_BLOCK_BLOCK_MMAD_PRELOAD_ASYNC_HPP
413

