107	    {
108	        BlockScheduler matmulBlockScheduler(params.problemShape, MakeCoord(L1TileShape::M, L1TileShape::N));
109	        uint32_t coreLoops = matmulBlockScheduler.GetCoreLoops();
110	
111	        Arch::Resource<ArchTag> resource;
112	        BlockMmad blockMmad(resource);
