114	        // Represent the full gm
115	        AscendC::GlobalTensor<ElementA> gmA;
116	        gmA.SetGlobalBuffer((__gm__ ElementA*)params.ptrA);
117	        AscendC::GlobalTensor<ElementB> gmB;
118	        gmB.SetGlobalBuffer((__gm__ ElementB*)params.ptrB);
119	        AscendC::GlobalTensor<ElementC> gmC;
