129	            MatrixCoord offsetB{blockCoord.k() * L1TileShape::K, blockCoord.n() * L1TileShape::N};
130	            MatrixCoord offsetC{blockCoord.m() * L1TileShape::M, blockCoord.n() * L1TileShape::N};
131	            int64_t gmOffsetA = params.layoutA.GetOffset(offsetA);
132	            int64_t gmOffsetB = params.layoutB.GetOffset(offsetB);
133	            int64_t gmOffsetC = params.layoutC.GetOffset(offsetC);
134	
135	            bool isFirstBlock = (loopIdx == AscendC::GetBlockIdx());
136	            bool hasNextBlock = false;
